        'admin.githubAuthenticationHint': 'Configure the GitHub App at runtime. The client secret is encrypted with WebSSH\'s persistent secret and is never returned to the browser.',
        'admin.githubSetupTitle': 'Set up the GitHub side first',
        'admin.githubSetupHint': 'Exact GitHub menus, values, permissions, and installation',
        'admin.githubSetupUrl': 'Choose the public WebSSH URL. Use HTTPS and form the callback as https://your-webssh-host/auth/github/callback. If WebSSH uses an application-root prefix, place it before /auth/github/callback.',
        'admin.githubSetupApp': 'Create a GitHub App. For a personal app, open Profile picture → Settings → Developer settings → GitHub Apps → New GitHub App. For an organization-owned app, open Profile picture → Your organizations → Settings → Developer settings → GitHub Apps → New GitHub App. Organization owners or designated GitHub App managers can create it.',
        'admin.githubSetupBasic': 'Complete “Basic information”. Give the app a unique name, set Homepage URL to the public WebSSH base URL, and set Callback URL to the exact value used below. Leave Setup URL empty and clear Active under Webhook; WebSSH does not receive webhooks.',
        'admin.githubSetupPermissions': 'Grant the minimum permissions. Keep all repository and account permissions at No access. Only when using Allowed organizations, open Permissions & events → Organization permissions and set Members to Read-only (Members: read).',
